+
+interface Args {
+    /** Room in which the permalink should be displayed. */
+    room?: Room;
+    /** When set forces the permalink type. */
+    type?: PillType;
+    /** Permalink URL. */
+    url?: string;
+}
+
+interface HookResult {
+    /** Member of the permalink target. Only set if the permalink refers to a user. */
+    member: RoomMember | null;
+    /** onClick function. Should be applied to the permalink. */
+    onClick: (e: ButtonEvent) => void;
+    /** ID of the permalink target, e.g. a user or room Id. */
+    resourceId: string | null;
+    /** Room of the permalink target. Only set if the permalink refers to a room. */
+    targetRoom: Room | null;
+    /**
+     * Displayable text of the permalink resource. Can for instance be a user or room name.
+     */
+    text: string | null;
+    type: PillType | null;
+}
+
+/**
+ * Can be used to retrieve all information needed to display a permalink.
+ */
+export const usePermalink: (args: Args) => HookResult = ({ room, type: forcedType, url }): HookResult => {
+    const [member, setMember] = useState<RoomMember | null>(null);
+    // room of the entity this permalink points to
+    const [targetRoom, setTargetRoom] = useState<Room | null>(room ?? null);
+
+    let resourceId: string | null = null;
+
+    if (url) {
+        const parseResult = parsePermalink(url);
+
+        if (parseResult?.primaryEntityId) {
+            resourceId = parseResult.primaryEntityId;
+        }
+    }
+
+    const prefix = resourceId ? resourceId[0] : "";
+    const type =
+        forcedType ??
+        {
+            "@": PillType.UserMention,
+            "#": PillType.RoomMention,
+            "!": PillType.RoomMention,
+        }[prefix] ??
+        null;
+
