@@ -0,0 +1,270 @@
+/*
+Copyright 2023 The Matrix.org Foundation C.I.C.
+
+Licensed under the Apache License, Version 2.0 (the "License");
+you may not use this file except in compliance with the License.
+You may obtain a copy of the License at
+
+    http://www.apache.org/licenses/LICENSE-2.0
+
+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { logger } from "matrix-js-sdk/src/logger";
+
+interface CacheItem<K, V> {
+    key: K;
+    value: V;
+    /** Next item in the list */
+    next: CacheItem<K, V> | null;
+    /** Previous item in the list */
+    prev: CacheItem<K, V> | null;
+}
+
+/**
+ * Least Recently Used cache.
+ * Can be initialised with a capacity and drops the least recently used items.
+ * This behaviour is designed to be exactly the same as `Map`, with the addition of the LRU behaviour.
+ *
+ * Implemented via a key lookup map and a double linked list:
+ *             head              tail
+ *              a next → b next → c → next null
+ *  null ← prev a ← prev b ← prev c
+ *
+ * @template K - Type of the key used to look up the values inside the cache
+ * @template V - Type of the values inside the cache
+ */
+export class LruCache<K, V> {
+    /** Head of the list. Least recently used item. */
+    private head: CacheItem<K, V> | null = null;
+    /** Tail of the list. Most recently used item. */
+    private tail: CacheItem<K, V> | null = null;
+    /** Key lookup map */
+    private map: Map<K, CacheItem<K, V>>;
+
+    /**
+     * @param capacity - Cache capacity.
+     * @throws {Error} - Raises an error if the cache capacity is less than 1.
+     */
+    public constructor(private capacity: number) {
+        if (this.capacity < 1) {
+            throw new Error("Cache capacity must be at least 1");
+        }
+
+        this.map = new Map();
+    }
+
+    /**
+     * Whether the cache contains an item under this key.
+     * Marks the item as most recently used.
+     *
+     * @param key - Key of the item
+     * @returns true: item in cache, else false
+     */
+    public has(key: K): boolean {
+        try {
+            return this.getItem(key) !== undefined;
+        } catch (e) {
+            // Should not happen but to be safe. Clear the cache and return false.
+            this.safeClear(e as Error);
+            return false;
+        }
+    }
+
+    /**
+     * Returns an item from the cache.
+     * Marks the item as most recently used.
+     *
+     * @param key - Key of the item
+     * @returns The value if found, else undefined
+     */
+    public get(key: K): V | undefined {
+        try {
+            return this.getItem(key)?.value;
+        } catch (e) {
+            // Should not happen but to be safe. Clear the cache and return undefined.
+            this.safeClear(e as Error);
+            return undefined;
+        }
+    }
+
+    /**
+     * Adds an item to the cache.
+     * A newly added item will be the set as the most recently used.
+     *
+     * @param key - Key of the item
+     * @param value - Item value
+     */
+    public set(key: K, value: V): void {
+        try {
+            this.safeSet(key, value);
+        } catch (e) {
+            // Should not happen but to be safe. Clear the cache.
+            this.safeClear(e as Error);
+        }
+    }
+
+    /**
+     * Deletes an item from the cache.
+     *
+     * @param key - Key of the item to be removed
+     */
+    public delete(key: K): void {
+        const item = this.map.get(key);
+
+        // Unknown item.
+        if (!item) return;
+
+        try {
+            this.removeItemFromList(item);
+            this.map.delete(key);
+        } catch (e) {
+            // Should not happen but to be safe. Clear the cache.
+            this.safeClear(e as Error);
+        }
+    }
+
+    /**
+     * Clears the cache.
+     */
+    public clear(): void {
+        this.map = new Map();
+        this.head = null;
+        this.tail = null;
+    }
+
+    /**
+     * Returns an iterator over the cached values.
+     */
+    public *values(): IterableIterator<V> {
+        for (const item of this.map.values()) {
+            yield item.value;
+        }
+    }
+
+    private safeSet(key: K, value: V): void {
+        const item = this.getItem(key);
+
+        if (item) {
+            // The item is already stored under this key. Update the value.
+            item.value = value;
+            return;
+        }
+
+        const newItem: CacheItem<K, V> = {
+            key,
+            value,
+            next: null,
+            prev: null,
+        };
+
+        if (this.tail) {
+            this.tail.next = newItem;
+            newItem.prev = this.tail;
+        }
+
+        this.tail = newItem;
+
+        if (!this.head) {
+            this.head = newItem;
+        }
+
+        // Add item to the map.
+        this.map.set(key, newItem);
+
+        if (this.map.size <= this.capacity) {
+            return;
+        }
+
+        // Map size exceeded the cache capacity. Drop the head item.
+        this.drop();
+    }
+
+    /**
+     * Removes the head from the cache.
+     * Also removes the item from the map.
+     */
+    private drop(): void {
+        if (!this.head) return;
+
+        this.map.delete(this.head.key);
+
+        if (!this.head.next) {
+            // No more items in the list.
+            this.head = null;
+            this.tail = null;
+            return;
+        }
+
+        this.head = this.head.next;
+        this.head.prev = null;
+    }
+
+    /**
+     * Looks up an item in the cache.
+     * Marks the item as most recently used.
+     *
+     * @param key - Key of the item
+     * @returns Cache item if present, else undefined
+     */
+    private getItem(key: K): CacheItem<K, V> | undefined {
+        const item = this.map.get(key);
+
+        // Not in cache.
+        if (!item) return undefined;
+
+        // Item is already the tail. No update required.
+        if (item === this.tail) return item;
+
+        this.removeItemFromList(item);
+
+        // Put item to the end.
+        item.next = null;
+        item.prev = this.tail;
+
+        if (this.tail) {
+            this.tail.next = item;
+        }
+
+        this.tail = item;
+
+        if (!this.head) {
+            this.head = item;
+        }
+
+        return item;
+    }
+
+    private removeItemFromList(item: CacheItem<K, V>): void {
+        if (item === this.head) {
+            this.head = item.next;
+        }
+
+        if (item === this.tail) {
+            this.tail = item.prev;
+        }
+
+        if (item.prev) {
+            item.prev.next = item.next;
+        }
+
+        if (item.next) {
+            item.next.prev = item.prev;
+        }
+
+        item.prev = null;
+        item.next = null;
+    }
+
+    /**
+     * Clears the cache and logs the error.
+     */
+    private safeClear(error: Error): void {
+        logger.warn("LruCache error", error);
+        this.clear();
+    }
+}

